# Compatible pipelines already have a reuse route without tarshare. This example
# copies the metadata generated by targets, unchanged, as version control would.
# It never reconstructs or edits the name-to-object ledger.
native_cas_metadata_example <- function(root = tempfile("native-cas-example-")) {
  dir.create(root)
  root <- normalizePath(root, winslash = "/")
  script <- file.path(root, "_targets.R")
  counter <- file.path(root, "computed.txt")
  cas <- file.path(root, "cas")
  writeLines(c(
    paste0("repository <- targets::tar_repository_cas_local(", deparse(cas), ")"),
    paste0("counter <- ", deparse(counter)),
    "compute <- function() {",
    "  cat('computed\\n', file = counter, append = TRUE)",
    "  42L",
    "}",
    "list(targets::tar_target(result, compute(), repository = repository))"
  ), script)
  first <- file.path(root, "first")
  second <- file.path(root, "second")
  run <- function(store) targets::tar_make(script = script, store = store,
    callr_function = NULL, reporter = "silent", envir = new.env(parent = baseenv()))
  run(first)
  dir.create(second)
  stopifnot(file.copy(file.path(first, "meta"), second, recursive = TRUE))
  run(second)
  stopifnot(identical(targets::tar_read_raw("result", store = second), 42L),
            identical(readLines(counter), "computed"))
  list(root = root, stores = c(first, second), computations = length(readLines(counter)))
}
# Run native_cas_metadata_example() after sourcing this file.
